const markStaleNodesOffline = `-- name: MarkStaleNodesOffline :many
UPDATE nodes SET state = 'offline'
WHERE state = 'online' AND last_heartbeat_at < $1
RETURNING id, code, name, last_heartbeat_at
`

type MarkStaleNodesOfflineRow struct {
	ID              int64
	Code            string
	Name            string
	LastHeartbeatAt *time.Time
}

func (q *Queries) MarkStaleNodesOffline(ctx context.Context, lastHeartbeatAt *time.Time) ([]MarkStaleNodesOfflineRow, error) {
	rows, err := q.db.Query(ctx, markStaleNodesOffline, lastHeartbeatAt)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []MarkStaleNodesOfflineRow{}
	for rows.Next() {
		var i MarkStaleNodesOfflineRow
		if err := rows.Scan(
			&i.ID,
			&i.Code,
			&i.Name,
			&i.LastHeartbeatAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

