const touchNodeHeartbeat = `-- name: TouchNodeHeartbeat :one
UPDATE nodes SET last_heartbeat_at = now(), state = 'online'
FROM (SELECT o.id, o.state FROM nodes o WHERE o.id = $1::bigint FOR UPDATE) AS prev
WHERE nodes.id = prev.id
RETURNING prev.state AS previous_state
`

func (q *Queries) TouchNodeHeartbeat(ctx context.Context, id int64) (string, error) {
	row := q.db.QueryRow(ctx, touchNodeHeartbeat, id)
	var previous_state string
	err := row.Scan(&previous_state)
	return previous_state, err
}

const touchNodePush = `-- name: TouchNodePush :exec
UPDATE nodes SET last_push_at = now() WHERE id = $1
`

func (q *Queries) TouchNodePush(ctx context.Context, id int64) error {
	_, err := q.db.Exec(ctx, touchNodePush, id)
	return err
}

const updateNode = `-- name: UpdateNode :one
UPDATE nodes SET
    name = $2, address = $3, port = $4, server_port = $5, rate = $6, tags = $7, settings = $8,
    sort = $9, backend = $10, updated_at = now(), version = version + 1
WHERE id = $1
RETURNING id, code, name, template_id, host, address, region, protocol, port, server_port, settings, rate, state, tags, sort, key_hash, key_cipher, allow_legacy_token, last_heartbeat_at, last_push_at, load, created_at, updated_at, version, backend, runtime, monthly_cost
`

type UpdateNodeParams struct {
	ID         int64
	Name       string
	Address    string
	Port       int32
	ServerPort int32
	Rate       float64
	Tags       []string
	Settings   json.RawMessage
	Sort       int32
	Backend    string
}

func (q *Queries) UpdateNode(ctx context.Context, arg UpdateNodeParams) (Node, error) {
	row := q.db.QueryRow(ctx, updateNode,
		arg.ID,
		arg.Name,
		arg.Address,
		arg.Port,
		arg.ServerPort,
		arg.Rate,
		arg.Tags,
		arg.Settings,
		arg.Sort,
		arg.Backend,
	)
	var i Node
	err := row.Scan(
		&i.ID,
		&i.Code,
		&i.Name,
		&i.TemplateID,
		&i.Host,
		&i.Address,
		&i.Region,
		&i.Protocol,
		&i.Port,
		&i.ServerPort,
		&i.Settings,
		&i.Rate,
		&i.State,
		&i.Tags,
		&i.Sort,
		&i.KeyHash,
		&i.KeyCipher,
		&i.AllowLegacyToken,
		&i.LastHeartbeatAt,
		&i.LastPushAt,
		&i.Load,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Version,
		&i.Backend,
		&i.Runtime,
		&i.MonthlyCost,
	)
	return i, err
}

