const usedServerPorts = `-- name: UsedServerPorts :many
SELECT server_port FROM nodes WHERE host = $1
`

func (q *Queries) UsedServerPorts(ctx context.Context, host string) ([]int32, error) {
	rows, err := q.db.Query(ctx, usedServerPorts, host)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int32{}
	for rows.Next() {
		var server_port int32
		if err := rows.Scan(&server_port); err != nil {
			return nil, err
		}
		items = append(items, server_port)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
